/* Draws a list of scrolling-texture strips (water) into the scratchpad. */
void draw_level09_scrolling_textured_strips(char *list, float t, int count, long tex0, long tex1) {
    int i;
    int j;
    int c;
    int *sp;
    int idx;
    float s0;
    float s1;
    queue_level09_strip_texture_packets_t(tex0, tex1, t);
    l09_packet[0] = 0x30000009;
    l09_packet[1] = (int)gaspar_strip_gs_setup_packet;
    l09_packet[2] = 0;
    l09_packet[3] = 0x50000009;
    l09_packet += 4;
    font_queue_vu_state();
    s0 = 1.0f - (float)(gaspar_frame_count & 0x7FF) * 0.00048828125f;
    s1 = s0 + s0 + 0.5f;
    sp = (int *)0x70000000;
    for (i = 0; i < 256; i++) {
        sp[i] = ((i * 0x89) & 0xF) * 0x20200 + 0x80787070;
    }
    for (i = 0; i < count; i++) {
        char *e = list + i * 64;
        idx = FastBSphereCheck(e, 256.0f);
        if (idx == -1) continue;
        for (j = 0; j < *(int *)(e + 0x1C); j++) {
            int n;
            float *src;
            float *a = (float *)0x70001000;
            float *b = (float *)0x70002000;
            n = ((Strip *)e)->idx[j + 1] - ((Strip *)e)->idx[j];
            src = (float *)(*(int *)(e + 0x14) + ((Strip *)e)->idx[j] * 8);
            for (c = 0; c < n; c++) {
                float f = *src++;
                *b++ = f;
                *a++ = f;
                *a++ = *src + s0;
                *b++ = *src++ + s1;
            }
            emit_textured_strip_packet(n, *(int *)(e + 0x10) + ((Strip *)e)->idx[j] * 12, 0x70000000, 0x70001000, 0x70002000, idx == 0);
        }
    }
}
